1	import React, { useId, useCallback, type CSSProperties, forwardRef } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import { useZimmTextInputState } from 'app/hooks/useZimmTextInputState';
5	
6	type ZimmTextInputProps = {
7	  label: string;
8	  type?: string;
9	  name?: string;
10	  inverse?: boolean;
11	  disabled?: boolean;
12	  helperText?: string;
13	  errorText?: string;
14	  onChange?: (value: string) => void;
15	  /** Controlled value — pass with `onChange` to let a parent form own the value. */
16	  value?: string;
17	  /** Initial value when uncontrolled. Ignored if `value` is provided. */
18	  defaultValue?: string;
19	  /**
20	   * Opt in to the clear-✕ shown once the field has a value. Defaults to false.
21	   *
22	   * Not in the design system: the extracted TextfieldV2 spec defines a `trailing-icon`
23	   * attribute and no `clearable` attribute, and SFCC-55's AC specifies the Stay in Touch
24	   * section as "an email input field and submit button" — two controls, not three. The
25	   * clear was originally added on the belief that Figma's footer glyph was an ✕; Kiera
26	   * confirmed (2026-08-20) it is the submit chevron, which `trailing` now carries.
27	   *
28	   * Kept as opt-in rather than deleted because a clear affordance is reasonable on a text
29	   * input atom (a search field would want one) — it just should not be the atom's decision
30	   * to impose. No consumer opts in today, so the footer renders one trailing control and
31	   * matches Figma.
32	   */
33	  clearable?: boolean;
34	  /**
35	   * Trailing icon-button slot. This IS in the design system: it maps to the extracted
36	   * TextfieldV2 spec's `trailing-icon` attribute (f2r/02-design/specs/components/text-input.md,
37	   * Figma node 40000265:374). ZimmInputAction injects the submit chevron here — Kiera confirmed
38	   * (2026-08-20) that the trailing glyph on the footer email field is the chevron, not an ✕.
39	   * Renders after the clear button below, which is a separate, unspecified addition.
40	   */
41	  trailing?: React.ReactNode;
42	  /** Render a full box-border (all four sides) instead of the default flush bottom-border only. */
43	  outlined?: boolean;
44	  style?: CSSProperties;
45	};
46	
47	/**
48	 * Atom — flush text input with floating label. Mirrors zimm-text-input contract
49	 * (flush + inverse variant).
50	 *
51	 * All styling lives in `zimmTextInput.css.ts`, co-located beside this file. The component owns only the
52	 * interaction state the theme cannot express: the value, focus, and whether the field is
53	 * filled — `filled` and `focused` are fed back into the recipe so it can resolve the
54	 * Figma colour cascade and the floated-label position.
55	 *
56	 * Accepts a forwarded ref pointing at the native `<input>` element — useful for
57	 * programmatic focus (e.g. `initialFocusRef` on a containing ZimmDrawer).
58	 */
59	export const ZimmTextInput = forwardRef<HTMLInputElement, ZimmTextInputProps>(
60	  (
61	    {
62	      label,
63	      type = 'text',
64	      name,
65	      inverse = false,
66	      disabled = false,
67	      helperText,
68	      errorText,
69	      onChange,
70	      value: controlledValue,
71	      defaultValue,
72	      clearable = false,
73	      trailing,
74	      outlined = false,
75	      style,
76	    },
77	    externalRef,
78	  ) => {
79	    const inputId = useId();
80	    const helperId = `${inputId}-helper`;
81	    const errorId = `${inputId}-error`;
82	    const hasError = !!errorText;
83	
84	    const { value, focused, inputRef, handleChange, handleClear, setFocused } = useZimmTextInputState({
85	      onChange,
86	      value: controlledValue,
87	      defaultValue,
88	    });
89	
90	    // Merge the hook's internal ref with any externally forwarded ref (e.g. initialFocusRef
91	    // from ZimmDrawer) so both handleClear's focus and the drawer's open-focus work correctly.
92	    const setRef = useCallback(
93	      (el: HTMLInputElement | null) => {
94	        (inputRef as React.MutableRefObject<HTMLInputElement | null>).current = el;
95	        if (typeof externalRef === 'function') externalRef(el);
96	        else if (externalRef) (externalRef as React.MutableRefObject<HTMLInputElement | null>).current = el;
97	      },
98	      // inputRef is a stable ref object (never reassigned); safe to omit from deps.
99	      // eslint-disable-next-line react-hooks/exhaustive-deps
100	      [externalRef],
101	    );
102	
103	    const styles = useMultiStyleConfig('ZimmTextInput', {
104	      inverse,
105	      disabled,
106	      hasError,
107	      focused,
108	      filled: value.length > 0,
109	      outlined,
110	    });
111	
112	    return (
113	      <chakra.div __css={styles.root} style={style}>
114	        <chakra.div __css={styles.row}>
115	          {/* content — label + input stacked */}
116	          <chakra.div __css={styles.content}>
117	            <chakra.label htmlFor={inputId} __css={styles.label}>
118	              {label}
119	            </chakra.label>
120	            <chakra.input
121	              id={inputId}
122	              ref={setRef}
123	              type={type}
124	              name={name}
125	              value={value}
126	              disabled={disabled}
127	              autoComplete={type === 'email' ? 'email' : undefined}
128	              onChange={handleChange}
129	              onFocus={() => setFocused(true)}
130	              onBlur={() => setFocused(false)}
131	              aria-invalid={hasError}
132	              aria-describedby={[helperText && helperId, hasError && errorId].filter(Boolean).join(' ') || undefined}
133	              __css={styles.input}
134	            />
135	          </chakra.div>
136	          {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
137	              field that opts into both shows clear then trailing icon. */}
138	          {clearable && !disabled && value.length > 0 && (
139	            <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
140	              <ZimmIcon type="close" size="sm" aria-hidden={true} />
141	            </chakra.button>
142	          )}
143	          {trailing}
144	        </chakra.div>
145	        {helperText && (
146	          <chakra.p id={helperId} __css={styles.helper}>
147	            {helperText}
